package app.bookey.domain.club;
import jakarta.persistence.*; import lombok.*; import java.time.Instant;
@Getter @Entity @Table(name="club_chat_unlocks", uniqueConstraints=@UniqueConstraint(columnNames={"club_id","user_id"})) @NoArgsConstructor(access=AccessLevel.PROTECTED)
public class ClubChatUnlock { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="club_id",nullable=false) private Long clubId; @Column(name="user_id",nullable=false) private Long userId; @Column(name="paid_by_user_id",nullable=false) private Long paidByUserId; @Column(name="cost_bookmarks",nullable=false) private int costBookmarks; @Column(name="unlocked_at",insertable=false,updatable=false) private Instant unlockedAt; public ClubChatUnlock(Long clubId,Long userId,Long paidByUserId,int cost){this.clubId=clubId;this.userId=userId;this.paidByUserId=paidByUserId;this.costBookmarks=cost;} }
